// Generates supabase/seed/irdai_rules.sql from src/lib/rules-engine/catalogue.ts so the
// database and the offline engine can never drift. Run: npm run seed:gen
import { mkdirSync, writeFileSync } from "node:fs";
import { RULES } from "../src/lib/rules-engine/catalogue";
import { normalise } from "../src/lib/rules-engine/match";

const q = (s: string) => `'${s.replace(/'/g, "''")}'`;

const out: string[] = [
  "-- GENERATED by scripts/gen-seed.ts — do not edit by hand.",
  "begin;",
];

for (const r of RULES) {
  out.push(
    `insert into irdai_rules (code, version, list, item_name, source, circular_ref, clause, effective_from, explanation_en, explanation_hi, rebuttal_template_en, rebuttal_template_hi)
values (${[r.code].map(q)}, 1, '${r.list}', ${q(r.itemName)}, ${q(r.source)}, ${q(r.circularRef)}, ${q(r.clause)}, ${q(r.effectiveFrom)}, ${q(r.explanationEn)}, ${q(r.explanationHi)}, ${q(r.rebuttalEn)}, ${q(r.rebuttalHi)})
on conflict (code, version) do nothing;`,
  );
  const phrases = [...new Set([r.itemName, ...r.synonyms].map((p) => normalise(p).trim()))];
  for (const p of phrases) {
    out.push(
      `insert into rule_synonyms (rule_id, phrase) select id, ${q(p)} from irdai_rules where code = ${q(r.code)} and version = 1 on conflict do nothing;`,
    );
  }
}
out.push("commit;", "");

mkdirSync("supabase/seed", { recursive: true });
writeFileSync("supabase/seed/irdai_rules.sql", out.join("\n"));
console.log(`wrote ${RULES.length} rules`);
